        for i,v in enumerate(o): walk(v,p+f'[{i}]')
walk(d)
EOF

cd "$TMPDIR" && python3 - <<'EOF'
import plistlib
d=plistlib.load(open('ad.plist','rb'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items():
            if k in ('codesign-allocate-result',) or 'launch' in str(v)[:0]:
                print(p+'/'+k); 
                for kk,vv in v.items(): print('   ',kk,':',repr(vv)[:400])
            walk(v,p+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,p+f'[{i}]')
walk(d)
# also collect all stderr that are nonempty
def errs(o,p=''):
    if isinstance(o,dict):
        if o.get('stderr') and 'warning: assigned but unused' not in o['stderr']:
            print('STDERR',p,'::',o.get('command','')[:120],'::',o['stderr'][:200].replace('\n',' | '))
        for k,v in o.items(): errs(v,p+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): errs(v,p+f'[{i}]')
errs(d)
EOF
